// Nomenclature des actes médicaux et paramédicaux — source : tarif
// prestataire (document "TARIF 2"), transcrite et dédoublonnée à la main.
// Sert de référentiel pour la saisie des Factures/Remboursements
// (PriseEnCharge) et des demandes d'Accord Préalable, et se rattache au
// tableau de garanties du contrat (categorieGarantie) pour la maîtrise des
// plafonds — voir model ActeMedical dans schema.prisma.
//
// Note de transcription : le document source contenait de nombreux quasi-
// doublons (le même acte saisi deux fois sous des libellés légèrement
// différents, parfois à des prix différents — notamment dans les familles
// ECHOGRAPHIE et EXAMENS LABORATOIRE, qui semblent résulter de la fusion de
// deux versions du tarif). Seuls les doublons certains (même libellé ou
// abréviation non ambiguë, même prix) ont été fusionnés ; les cas
// ambigus (même acte apparent mais prix différents) ont été conservés
// séparément par prudence plutôt que fusionnés au risque de perdre une
// ligne tarifaire réellement distincte — à vérifier au besoin.

export interface ActeMedicalSeed {
  libelle: string;
  famille: string;
  prixDefaut: number;
  categorieGarantie?: string;
  // TPS (2026-08) — chambre/hébergement et médicaments restent exonérés
  // même chez un prestataire assujetti (voir Prestataire.tpsAssujetti,
  // SanteService.calculerTps).
  exonereTps?: boolean;
}

